=== FILE: rr_arbiter.v ===
// rr_arbiter: round-robin arbiter for N requesters (default 4).
// Interface: interface_spec.md. Implementation plan: microarchitecture.md.
// grant is combinational from req and ptr; ptr moves to one past the winner
// on every rising edge with a grant, wrapping explicitly at N.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);
    localparam integer PW = (N > 1) ? $clog2(N) : 1;

    reg [PW-1:0] ptr;
    reg [PW-1:0] ptr_next;
    reg          found;
    integer      i;
    integer      j;

    // Grant: first requester at or after ptr, wrapping from N-1 to 0.
    // Pass 1 searches requesters at or above ptr; pass 2 (the wrap) searches
    // from 0 and is used only when pass 1 found no one.
    always @* begin
        grant = {N{1'b0}};
        found = 1'b0;
        for (i = 0; i < N; i = i + 1) begin
            if (!found && req[i] && (i[PW-1:0] >= ptr)) begin
                found    = 1'b1;
                grant[i] = 1'b1;
            end
        end
        for (i = 0; i < N; i = i + 1) begin
            if (!found && req[i]) begin
                found    = 1'b1;
                grant[i] = 1'b1;
            end
        end
    end

    // Next pointer: one past the winner, 0 after N-1; hold with no grant.
    always @* begin
        ptr_next = ptr;
        if (grant != {N{1'b0}}) begin
            ptr_next = {PW{1'b0}};
            for (j = 1; j < N; j = j + 1) begin
                if (grant[j-1]) ptr_next = j[PW-1:0];
            end
        end
    end

    // Pointer register: synchronous active-low reset to 0.
    always @(posedge clk) begin
        if (!rst_n) ptr <= {PW{1'b0}};
        else        ptr <= ptr_next;
    end

`ifdef FORMAL
    localparam integer LASTI = N - 1;

    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active on the first cycle.
    always @(*) if (!f_past_valid) assume(!rst_n);

    // Index of the granted requester.
    reg [PW-1:0] f_winner;
    integer f_i;
    always @(*) begin
        f_winner = {PW{1'b0}};
        for (f_i = 0; f_i < N; f_i = f_i + 1)
            if (grant[f_i]) f_winner = f_i[PW-1:0];
    end

    // Reference model: walk upward from ptr, wrapping at N.
    reg [N-1:0] f_exp_grant;
    reg         f_found;
    integer     f_k;
    integer     f_idx;
    integer     f_exp_idx;
    integer     f_b;
    always @(*) begin
        f_found   = 1'b0;
        f_exp_idx = 0;
        f_idx     = 0;
        for (f_k = 0; f_k < N; f_k = f_k + 1) begin
            f_idx = ptr + f_k;
            if (f_idx >= N) f_idx = f_idx - N;
            if (!f_found && req[f_idx]) begin
                f_found   = 1'b1;
                f_exp_idx = f_idx;
            end
        end
        f_exp_grant = {N{1'b0}};
        for (f_b = 0; f_b < N; f_b = f_b + 1)
            f_exp_grant[f_b] = f_found && (f_exp_idx == f_b);
    end

    always @(*) begin
        // One-hot or zero, only to a requester, work conserving.
        assert((grant & (grant - 1'b1)) == {N{1'b0}});
        assert((grant & ~req) == {N{1'b0}});
        assert((req == {N{1'b0}}) || (grant != {N{1'b0}}));
        if (f_past_valid) begin
            // Pointer in range; grant follows round-robin order from ptr
            // (no requester sits between the pointer and the winner).
            assert(ptr <= LASTI);
            assert(grant == f_exp_grant);
        end
    end

    // Pointer update rule.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n))
                assert(ptr == {PW{1'b0}});
            else if ($past(grant) == {N{1'b0}})
                assert(ptr == $past(ptr));
            else if ($past(f_winner) == LASTI)
                assert(ptr == {PW{1'b0}});
            else
                assert(ptr == $past(f_winner) + 1'b1);
        end
    end

    // Fairness: cycles waited with the request held, at most N-1.
    genvar f_g;
    generate
        for (f_g = 0; f_g < N; f_g = f_g + 1) begin : f_fair
            reg  [PW:0] f_wait;
            wire [PW:0] f_dist;
            assign f_dist = (f_g >= ptr) ? (f_g - ptr) : (f_g + N - ptr);

            always @(posedge clk) begin
                if (!rst_n)
                    f_wait <= {(PW+1){1'b0}};
                else if (req[f_g] && !grant[f_g])
                    f_wait <= f_wait + 1'b1;
                else
                    f_wait <= {(PW+1){1'b0}};
            end

            always @(*) begin
                if (f_past_valid) begin
                    assert(f_wait <= LASTI);
                    // Induction invariant: wait plus distance from ptr.
                    assert(f_wait + f_dist <= LASTI);
                end
            end

            always @(*) begin
                cover(f_past_valid && rst_n && grant[f_g]);
                cover(f_past_valid && (f_wait == LASTI));
            end
        end
    endgenerate

    always @(*) begin
        cover(f_past_valid && rst_n && (req == {N{1'b1}}));
        cover(f_past_valid && rst_n && (req == {N{1'b0}}));
        cover(f_past_valid && !rst_n && (req != {N{1'b0}}));
    end

    always @(posedge clk) begin
        if (f_past_valid)
            cover($past(rst_n) && ($past(ptr) == LASTI) && (ptr == {PW{1'b0}}));
    end
`endif
endmodule

`ifdef FORMAL
