// Self-checking testbench for rr_arbiter: N=4 and N=5 side by side, each
// checked every cycle against a reference pointer model.
module rr_arbiter_tb;
    reg        clk;
    reg        rst_n;
    reg  [3:0] req4;
    reg  [4:0] req5;
    wire [3:0] grant4;
    wire [4:0] grant5;

    rr_arbiter #(.N(4)) dut4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
    rr_arbiter #(.N(5)) dut5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));

    initial clk = 1'b0;
    always #5 clk = ~clk;

    integer passed;
    integer failed;
    integer cyc;
    integer seed;
    integer rnd;
    integer rnd2;
    integer t;
    integer b;
    integer fullv;

    integer ref_ptr  [0:1];
    integer ref_next [0:1];
    integer waitc    [0:15];
    integer maxwait  [0:1];
    integer cov_idle [0:1];
    integer cov_all  [0:1];
    integer cov_held [0:1];
    integer cov_rst  [0:1];
    reg [7:0] seen_alone [0:1];
    reg [7:0] prev_req   [0:1];

    reg       started;
    reg       rot_phase;
    integer   rot_k;
    reg [7:0] v;
    reg       rb;

    reg [8*64-1:0] nonce;

    function [7:0] onehot8;
        input integer idx;
        begin
            onehot8 = 8'h00;
            if (idx >= 0 && idx < 8) onehot8[idx] = 1'b1;
        end
    endfunction

    // Check one arbiter for the current cycle and compute its next pointer.
    task check_dut;
        input integer d;
        input integer n;
        input [7:0]   r;
        input [7:0]   g;
        input         rst_bit;
        integer   w;
        integer   k;
        integer   idx;
        integer   full;
        reg [7:0] expv;
        reg       over;
        begin
            // Reference: first requester at or after the pointer, wrapping at n.
            w = -1;
            for (k = 0; k < n; k = k + 1) begin
                idx = ref_ptr[d] + k;
                if (idx >= n) idx = idx - n;
                if (w < 0 && r[idx]) w = idx;
            end
            expv = onehot8(w);
            if (g === expv) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d cycle %0d: req %b grant %b, expected %b (pointer %0d)",
                       n, cyc, r, g, expv, ref_ptr[d]);
            end

            // Strict rotation after reset with everyone requesting.
            if (rot_phase) begin
                if (g === onehot8(rot_k % n)) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $error("N=%0d rotation step %0d: grant %b, expected %b",
                           n, rot_k, g, onehot8(rot_k % n));
                end
            end

            // Fairness: consecutive cycles a held request is not granted.
            over = 1'b0;
            for (k = 0; k < n; k = k + 1) begin
                if (rst_bit && r[k] && (waitc[d*8+k] > 0) &&
                    (((r ^ prev_req[d]) & ~onehot8(k)) != 8'h00))
                    cov_held[d] = cov_held[d] + 1;
                if (!rst_bit)
                    waitc[d*8+k] = 0;
                else if (r[k] && !g[k])
                    waitc[d*8+k] = waitc[d*8+k] + 1;
                else
                    waitc[d*8+k] = 0;
                if (waitc[d*8+k] > n - 1) over = 1'b1;
                if (waitc[d*8+k] > maxwait[d]) maxwait[d] = waitc[d*8+k];
            end
            if (!over) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d cycle %0d: a held request waited more than %0d cycles",
                       n, cyc, n - 1);
            end

            // Next pointer.
            if (!rst_bit)    ref_next[d] = 0;
            else if (w >= 0) ref_next[d] = (w == n - 1) ? 0 : w + 1;
            else             ref_next[d] = ref_ptr[d];

            // Coverage.
            full = (1 << n) - 1;
            if (rst_bit && (r == 8'h00)) cov_idle[d] = cov_idle[d] + 1;
            if (rst_bit && (r == full[7:0])) cov_all[d] = cov_all[d] + 1;
            if (rst_bit && (r != 8'h00) && ((r & (r - 8'd1)) == 8'h00) && (g === r))
                seen_alone[d] = seen_alone[d] | r;
            if (!rst_bit && started && (r != 8'h00)) cov_rst[d] = cov_rst[d] + 1;
            prev_req[d] = r;
        end
    endtask

    // One cycle: drive at the falling edge, check, then commit the model at
    // the rising edge.
    task step;
        input [3:0] r4;
        input [4:0] r5;
        input       rst_bit;
        begin
            @(negedge clk);
            req4  = r4;
            req5  = r5;
            rst_n = rst_bit;
            #1;
            check_dut(0, 4, {4'b0000, req4}, {4'b0000, grant4}, rst_bit);
            check_dut(1, 5, {3'b000, req5}, {3'b000, grant5}, rst_bit);
            @(posedge clk);
            ref_ptr[0] = ref_next[0];
            ref_ptr[1] = ref_next[1];
            cyc = cyc + 1;
            if (rst_bit) started = 1'b1;
        end
    endtask

    initial begin
        passed    = 0;
        failed    = 0;
        cyc       = 0;
        seed      = 1234567;
        started   = 1'b0;
        rot_phase = 1'b0;
        rot_k     = 0;
        req4      = 4'b0000;
        req5      = 5'b00000;
        rst_n     = 1'b0;
        v         = 8'h00;
        rb        = 1'b1;
        for (b = 0; b < 2; b = b + 1) begin
            ref_ptr[b]    = 0;
            ref_next[b]   = 0;
            maxwait[b]    = 0;
            cov_idle[b]   = 0;
            cov_all[b]    = 0;
            cov_held[b]   = 0;
            cov_rst[b]    = 0;
            seen_alone[b] = 8'h00;
            prev_req[b]   = 8'h00;
        end
        for (b = 0; b < 16; b = b + 1) waitc[b] = 0;
        nonce = {64{8'h00}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {64{8'h00}};

        // Reset, then no requests.
        step(4'b0000, 5'b00000, 1'b0);
        step(4'b0000, 5'b00000, 1'b0);
        step(4'b0000, 5'b00000, 1'b1);
        step(4'b0000, 5'b00000, 1'b1);
        step(4'b0000, 5'b00000, 1'b1);

        // Everyone requesting after reset: strict rotation, longest wait N-1.
        step(4'b0000, 5'b00000, 1'b0);
        rot_phase = 1'b1;
        rot_k     = 0;
        for (t = 0; t < 20; t = t + 1) begin
            step(4'b1111, 5'b11111, 1'b1);
            rot_k = rot_k + 1;
        end
        rot_phase = 1'b0;

        // Each requester alone.
        for (t = 0; t < 5; t = t + 1) begin
            v = onehot8(t);
            step(v[3:0], v[4:0], 1'b1);
            step(v[3:0], v[4:0], 1'b1);
        end

        // A held request among changing others.
        for (t = 0; t < 60; t = t + 1) begin
            rnd = $random(seed);
            step(rnd[3:0] | 4'b0100, rnd[4:0] | 5'b01000, 1'b1);
        end

        // Reset during traffic.
        step(4'b1111, 5'b11111, 1'b1);
        step(4'b1111, 5'b11111, 1'b1);
        step(4'b1111, 5'b11111, 1'b1);
        step(4'b1010, 5'b10110, 1'b0);
        step(4'b1010, 5'b10110, 1'b0);
        for (t = 0; t < 6; t = t + 1) step(4'b1111, 5'b11111, 1'b1);

        // Random subsets, sparse and dense, with occasional resets.
        for (t = 0; t < 400; t = t + 1) begin
            rnd  = $random(seed);
            rnd2 = $random(seed);
            v  = (t % 3 == 0) ? (rnd[7:0] & rnd2[7:0]) : (rnd[7:0] | rnd2[7:0]);
            rb = ((t % 97) != 50);
            step(v[3:0], v[7:3], rb);
        end

        // Coverage goals.
        for (b = 0; b < 2; b = b + 1) begin
            fullv = (1 << (4 + b)) - 1;
            if (cov_idle[b] > 0) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d coverage: no-request cycle not reached", 4 + b);
            end
            if (seen_alone[b] == fullv[7:0]) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d coverage: not every requester granted alone (%b)", 4 + b, seen_alone[b]);
            end
            if (cov_all[b] > 0) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d coverage: all-requesting cycle not reached", 4 + b);
            end
            if (cov_held[b] > 0) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d coverage: held request among changing others not reached", 4 + b);
            end
            if (maxwait[b] == 3 + b) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d coverage: longest wait %0d, expected %0d", 4 + b, maxwait[b], 3 + b);
            end
            if (cov_rst[b] > 0) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d coverage: reset during traffic not reached", 4 + b);
            end
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
